head.b:skin:
:root {
  --tv-navy-950: #060b16;
  --tv-navy-900: #0b1324;
  --tv-navy-800: #13203b;
  --tv-blue-600: #2563eb;
  --tv-ink: #0f172a;
  --tv-muted: #475569;
  --tv-subtle: #475569;
  --tv-border: #e2e8f0;
  --tv-surface: #f8fafc;
  --tv-white: #ffffff;
  --tv-font-display: "Playfair Display", Georgia, serif;
  --tv-font-sans: "Plus Jakarta Sans", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  --tv-font-mono: "JetBrains Mono", ui-monospace, monospace;
}
*, *::before, *::after { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body { margin: 0; font-family: var(--tv-font-sans); color: var(--tv-ink); background: var(--tv-white); line-height: 1.65; -webkit-font-smoothing: antialiased; }
a { color: inherit; text-decoration: none; }
img { max-width: 100%; height: auto; display: block; }
a:focus-visible, button:focus-visible, input:focus-visible { outline: 2px solid var(--tv-blue-600); outline-offset: 2px; }
.tv-skip-link { position: absolute; left: -9999px; top: 8px; z-index: 100; background: #2563eb; color: #ffffff; padding: 10px 16px; border-radius: 6px; font-weight: 600; font-size: 0.875rem; }
.tv-skip-link:focus { left: 16px; }
.tv-container { width: 100%; max-width: 1200px; margin: 0 auto; padding: 0 20px; }
.tv-header { position: sticky; top: 0; z-index: 50; background: rgba(11, 19, 36, 0.97); border-bottom: 1px solid rgba(255,255,255,0.1); color: #ffffff; }
.tv-header-inner { display: flex; align-items: center; justify-content: space-between; gap: 20px; min-height: 66px; }
.tv-brand-wrap { display: flex; flex-direction: column; flex-shrink: 0; }
.tv-brand { font-family: var(--tv-font-display); font-size: 1.375rem; font-weight: 700; letter-spacing: 0.04em; white-space: nowrap; line-height: 1.1; }
.tv-tagline { font-size: 0.6875rem; color: #93c5fd; letter-spacing: 0.04em; white-space: nowrap; }
.tv-nav { display: flex; align-items: center; gap: 16px; overflow-x: auto; }
.tv-nav a { font-size: 0.875rem; font-weight: 500; color: #cbd5e1; white-space: nowrap; padding: 6px 0; }
.tv-nav a:hover { color: #ffffff; text-decoration: underline; text-underline-offset: 6px; }
.tv-mobile-search { display: none; width: 100%; margin-top: 8px; }
.tv-header-actions { display: flex; align-items: center; gap: 10px; flex-shrink: 0; }
.tv-search-form { display: flex; align-items: center; gap: 6px; background: #13203b; border: 1px solid rgba(255,255,255,0.18); border-radius: 8px; padding: 4px 8px; }
.tv-search-form input { background: transparent; border: 0; color: #ffffff; font-size: 0.875rem; width: 145px; outline: none; }
.tv-search-form input::placeholder { color: #cbd5e1; }
.tv-search-form button { background: #2563eb; color: #ffffff; border: 0; border-radius: 6px; padding: 6px 12px; font-size: 0.8125rem; font-weight: 600; cursor: pointer; flex-shrink: 0; }
.tv-404-search { display: flex; align-items: center; gap: 8px; background: #13203b; border: 1px solid rgba(255,255,255,0.22); border-radius: 8px; padding: 6px 10px; max-width: 400px; }
.tv-404-search input { background: transparent; border: 0; color: #ffffff; font-size: 0.875rem; width: 100%; outline: none; }
.tv-404-search input::placeholder { color: #cbd5e1; }
.tv-404-search button { background: #2563eb; color: #ffffff; border: 0; border-radius: 6px; padding: 7px 14px; font-size: 0.8125rem; font-weight: 600; cursor: pointer; flex-shrink: 0; }
.tv-menu-toggle { display: none; background: transparent; border: 1px solid rgba(255,255,255,0.28); color: #ffffff; border-radius: 8px; padding: 7px 12px; font-size: 0.8125rem; font-weight: 600; cursor: pointer; }
.tv-hero-banner { background: linear-gradient(135deg, #060b16 0%, #0b1324 65%, #13203b 100%); color: #ffffff; padding: 42px 0; border-bottom: 1px solid #1e293b; }
.tv-hero-kicker { display: inline-block; font-family: var(--tv-font-mono); font-size: 0.75rem; letter-spacing: 0.08em; text-transform: uppercase; color: #93c5fd; margin-bottom: 10px; }
.tv-hero-banner h1 { font-family: var(--tv-font-display); font-size: clamp(2rem, 4vw, 3rem); line-height: 1.15; margin: 0 0 10px; }
.tv-hero-banner p { margin: 0; color: #cbd5e1; max-width: 64ch; }
.tv-hero-topics { display: flex; flex-wrap: wrap; gap: 10px; margin-top: 20px; }
.tv-hero-topics a { background: rgba(255,255,255,0.08); border: 1px solid rgba(255,255,255,0.18); border-radius: 8px; padding: 6px 12px; font-size: 0.8125rem; color: #e2e8f0; }
.tv-hero-topics a:hover { background: #2563eb; border-color: #2563eb; color: #ffffff; }
.tv-clock-bar { background: #060b16; color: #cbd5e1; border-bottom: 1px solid rgba(255,255,255,0.1); font-family: var(--tv-font-mono); font-size: 0.75rem; padding: 8px 0; }
.tv-clock-inner { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 12px; }
.tv-clock-cities { display: flex; flex-wrap: wrap; gap: 14px; }
.tv-home-desks { background: #f8fafc; border-bottom: 1px solid var(--tv-border); padding: 28px 0; }
.tv-home-desk-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 18px; }
.tv-desk-card { background: #ffffff; border: 1px solid var(--tv-border); border-radius: 10px; padding: 18px; display: flex; flex-direction: column; justify-content: space-between; }
.tv-desk-card h2 { font-family: var(--tv-font-display); font-size: 1.125rem; margin: 0 0 6px; color: var(--tv-ink); }
.tv-desk-card p { font-size: 0.875rem; color: var(--tv-muted); margin: 0 0 12px; }
.tv-section-heading { display: flex; align-items: baseline; justify-content: space-between; border-bottom: 1px solid var(--tv-border); padding-bottom: 10px; margin-bottom: 22px; }
.tv-section-heading h2 { font-family: var(--tv-font-display); font-size: 1.5rem; margin: 0; }
.tv-status-banner { background: var(--tv-surface); border: 1px solid var(--tv-border); border-left: 4px solid var(--tv-blue-600); border-radius: 10px; padding: 18px 20px; margin-bottom: 24px; }
.tv-status-banner h1 { font-family: var(--tv-font-display); font-size: 1.5rem; margin: 0 0 4px; }
.tv-status-banner p { margin: 0; font-size: 0.9375rem; color: var(--tv-muted); }
.tv-main { padding: 36px 0 64px; }
.tv-layout { display: grid; grid-template-columns: minmax(0, 1fr) 320px; gap: 40px; align-items: start; }
.tv-post-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 28px; }
.tv-card { border: 1px solid var(--tv-border); border-radius: 10px; overflow: hidden; background: #ffffff; display: flex; flex-direction: column; }
.tv-card-media { aspect-ratio: 16 / 10; background: linear-gradient(135deg, #060b16 0%, #0b1324 70%, #1e3a8a 100%); overflow: hidden; display: flex; align-items: center; justify-content: center; position: relative; }
.tv-card-media img { width: 100%; height: 100%; object-fit: cover; }
.tv-card-media-fallback { display: flex; flex-direction: column; align-items: center; justify-content: center; text-align: center; padding: 16px; color: #cbd5e1; width: 100%; height: 100%; }
.tv-card-media.is-fallback .tv-card-media-fallback { display: flex; }
.tv-card-media-brand { font-family: var(--tv-font-display); font-size: 1.125rem; font-weight: 700; color: #ffffff; letter-spacing: 0.06em; }
.tv-card-media-cat { font-family: var(--tv-font-mono); font-size: 0.6875rem; text-transform: uppercase; letter-spacing: 0.08em; color: #93c5fd; margin-top: 4px; }
.tv-card-body { padding: 20px; display: flex; flex-direction: column; flex: 1; }
.tv-meta-line { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; font-size: 0.75rem; color: var(--tv-subtle); margin-bottom: 10px; }
.tv-cat-badge { color: #1d4ed8; font-weight: 600; }
.tv-card-title { font-family: var(--tv-font-display); font-size: 1.35rem; line-height: 1.28; margin: 0 0 10px; color: var(--tv-ink); }
.tv-card-excerpt { font-size: 0.9375rem; color: var(--tv-muted); margin: 0 0 16px; flex: 1; }
.tv-read-link { font-size: 0.875rem; font-weight: 600; color: #1d4ed8; }
.tv-breadcrumb { font-size: 0.8125rem; color: var(--tv-subtle); margin-bottom: 16px; }
.tv-article-title { font-family: var(--tv-font-display); font-size: clamp(2rem, 3.6vw, 2.85rem); line-height: 1.15; margin: 0 0 14px; }
.tv-article-byline { display: flex; flex-wrap: wrap; align-items: center; gap: 10px; padding: 12px 0 18px; margin-bottom: 22px; border-bottom: 1px solid var(--tv-border); font-size: 0.8125rem; color: var(--tv-muted); }
.tv-article-cover { aspect-ratio: 16 / 9; border-radius: 10px; overflow: hidden; background: #0b1324; margin-bottom: 24px; }
.tv-article-cover img { width: 100%; height: 100%; object-fit: cover; }
.tv-toc { background: var(--tv-surface); border: 1px solid var(--tv-border); border-radius: 10px; padding: 18px 20px; margin: 24px 0; }
.tv-toc h2 { font-size: 0.9375rem; margin: 0 0 10px; }
.tv-toc ul { margin: 0; padding-left: 18px; }
.tv-toc li { margin-bottom: 6px; font-size: 0.875rem; color: #1d4ed8; }
.tv-article-body { max-width: 68ch; font-size: 1.0625rem; line-height: 1.8; overflow-wrap: break-word; }
.tv-article-body h2, .tv-article-body h3 { font-family: var(--tv-font-display); margin-top: 2rem; line-height: 1.28; }
.tv-article-body a { color: #1d4ed8; text-decoration: underline; }
.tv-labels-row { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 24px; }
.tv-label-link { border: 1px solid var(--tv-border); background: var(--tv-surface); border-radius: 6px; padding: 4px 10px; font-size: 0.75rem; font-weight: 600; color: var(--tv-muted); }
.tv-share-bar { display: flex; flex-wrap: wrap; align-items: center; gap: 10px; margin-top: 28px; padding-top: 20px; border-top: 1px solid var(--tv-border); }
.tv-share-btn { display: inline-flex; align-items: center; padding: 8px 14px; border: 1px solid #cbd5e1; background: #ffffff; border-radius: 8px; font-size: 0.8125rem; font-weight: 600; color: var(--tv-ink); cursor: pointer; }
.tv-author-card { display: flex; gap: 16px; align-items: flex-start; border: 1px solid var(--tv-border); background: var(--tv-surface); border-radius: 10px; padding: 20px; margin-top: 28px; }
.tv-author-badge { width: 52px; height: 52px; border-radius: 10px; background: #0b1324; color: #ffffff; font-family: var(--tv-font-display); font-size: 1.375rem; font-weight: 700; display: flex; align-items: center; justify-content: center; flex-shrink: 0; }
.tv-author-card h3 { margin: 0 0 4px; font-size: 1rem; }
.tv-author-card p { margin: 0 0 8px; font-size: 0.875rem; color: var(--tv-muted); }
.tv-author-links { display: flex; flex-wrap: wrap; gap: 14px; font-size: 0.8125rem; font-weight: 600; color: #1d4ed8; }
.tv-404-card { background: #0b1324; color: #ffffff; border-radius: 12px; padding: 40px 28px; }
.tv-404-code { font-family: var(--tv-font-mono); font-size: 0.875rem; color: #93c5fd; margin-bottom: 8px; }
.tv-404-card h1 { font-family: var(--tv-font-display); font-size: clamp(1.75rem, 3vw, 2.5rem); margin: 0 0 12px; }
.tv-404-card p { color: #cbd5e1; max-width: 58ch; margin: 0 0 24px; }
.tv-404-actions { display: flex; flex-wrap: wrap; gap: 12px; margin-bottom: 24px; }
.tv-btn-primary { background: #2563eb; color: #ffffff; border-radius: 8px; padding: 10px 18px; font-size: 0.875rem; font-weight: 600; }
.tv-ad-slot { min-height: 100px; margin: 28px 0; padding: 12px; background: var(--tv-surface); border: 1px solid var(--tv-border); border-radius: 8px; text-align: center; }
.tv-inarticle-ad { min-height: 120px; }
.tv-ad-label { display: block; font-size: 0.6875rem; letter-spacing: 0.08em; text-transform: uppercase; color: var(--tv-subtle); margin-bottom: 6px; }
.tv-sidebar-box { border: 1px solid var(--tv-border); border-radius: 10px; padding: 20px; margin-bottom: 24px; background: #ffffff; }
.tv-sidebar-box h2, .tv-sidebar-box h3 { font-size: 1rem; margin: 0 0 14px; padding-bottom: 10px; border-bottom: 1px solid var(--tv-border); }
.tv-sidebar-box .widget-content ul { margin: 0; padding-left: 18px; }
.tv-sidebar-box ul { margin: 0; padding-left: 18px; }
.tv-sidebar-box li { margin-bottom: 8px; font-size: 0.875rem; color: var(--tv-muted); }
.tv-pagination { display: flex; justify-content: space-between; margin-top: 36px; padding-top: 20px; border-top: 1px solid var(--tv-border); font-weight: 600; color: #1d4ed8; }
.tv-footer { background: #060b16; color: #cbd5e1; padding: 48px 0 32px; margin-top: 48px; }
.tv-footer-grid { display: grid; grid-template-columns: 2fr 1fr 1fr 1fr; gap: 32px; }
.tv-footer h4 { color: #ffffff; margin: 0 0 12px; font-size: 0.9375rem; }
.tv-footer ul { list-style: none; padding: 0; margin: 0; }
.tv-footer li { margin-bottom: 8px; font-size: 0.875rem; }
.tv-footer-bottom { margin-top: 32px; padding-top: 20px; border-top: 1px solid rgba(255,255,255,0.1); display: flex; flex-wrap: wrap; justify-content: space-between; gap: 12px; font-size: 0.8125rem; color: #cbd5e1; }
@media (max-width: 1024px) { .tv-search-form input { width: 120px; } .tv-nav { gap: 12px; } }
@media (max-width: 960px) { .tv-layout, .tv-post-grid, .tv-home-desk-grid { grid-template-columns: 1fr; } .tv-footer-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@media (max-width: 768px) {
  .tv-nav { display: none; }
  .tv-nav.is-open { display: flex; flex-direction: column; align-items: stretch; position: absolute; top: 66px; left: 0; right: 0; background: #0b1324; padding: 16px 20px; border-bottom: 1px solid rgba(255,255,255,0.12); z-index: 60; box-shadow: 0 12px 24px rgba(0,0,0,0.35); }
  .tv-nav.is-open .tv-mobile-search { display: flex; }
  .tv-nav.is-open .tv-mobile-search input { width: 100%; }
  .tv-menu-toggle { display: inline-flex; align-items: center; }
  .tv-header-actions .tv-search-form { display: none; }
  .tv-footer-grid { grid-template-columns: 1fr; }
  .tv-author-card { flex-direction: column; }
}

body.script:
//
(function () {
  'use strict';

  function normalizeBloggerUrl(url) {
    return String(url || '')
      .replace(/^https?:\/\//i, '')
      .replace(/[?#].*$/, '')
      .replace(/\/+$/, '');
  }

  // 0. Live Digital World Clock (Homepage Bar)
  var liveDateEl = document.getElementById('tv-live-date');
  var liveClocksEl = document.getElementById('tv-live-clocks');
  if (liveDateEl && liveClocksEl) {
    function updateClocks() {
      var now = new Date();
      liveDateEl.textContent = now.toUTCString().replace('GMT', 'UTC');
      var zones = [
        ['NYC', 'America/New_York'],
        ['LON', 'Europe/London'],
        ['DEL', 'Asia/Kolkata'],
        ['TYO', 'Asia/Tokyo']
      ];
      liveClocksEl.textContent = '';
      zones.forEach(function (z) {
        var span = document.createElement('span');
        try {
          var t = now.toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit', timeZone: z[1] });
          span.textContent = z[0] + ': ' + t;
        } catch (e) {
          span.textContent = z[0];
        }
        liveClocksEl.appendChild(span);
      });
    }
    updateClocks();
    setInterval(updateClocks, 60000);
  }

  // 1. Mobile Navigation Drawer + Escape + Outside Click
  var menuBtn = document.getElementById('tv-menu-toggle');
  var navEl = document.getElementById('tv-primary-nav');
  if (menuBtn && navEl) {
    menuBtn.addEventListener('click', function () {
      var expanded = menuBtn.getAttribute('aria-expanded') === 'true';
      menuBtn.setAttribute('aria-expanded', String(!expanded));
      navEl.classList.toggle('is-open');
    });
    document.addEventListener('keydown', function (event) {
      if (event.key === 'Escape' && navEl.classList.contains('is-open')) {
        navEl.classList.remove('is-open');
        menuBtn.setAttribute('aria-expanded', 'false');
      }
    });
    document.addEventListener('click', function (event) {
      if (
        navEl.classList.contains('is-open') &&
        !navEl.contains(event.target) &&
        !menuBtn.contains(event.target)
      ) {
        navEl.classList.remove('is-open');
        menuBtn.setAttribute('aria-expanded', 'false');
      }
    });
  }

  // 2. Deduplicate Featured Cover if Post Body Starts With Same Image
  var articleCover = document.getElementById('tv-article-cover');
  var articleBody = document.getElementById('tv-article-body');
  if (articleCover && articleBody) {
    var coverImg = articleCover.querySelector('img');
    var firstBodyImg = articleBody.querySelector('img');
    if (
      coverImg &&
      firstBodyImg &&
      normalizeBloggerUrl(coverImg.src) === normalizeBloggerUrl(firstBodyImg.src)
    ) {
      articleCover.style.display = 'none';
    }
  }

  // 3. Automatic Table of Contents on Post Pages
  var tocList = document.getElementById('tv-toc-list');
  var tocBox = document.getElementById('tv-toc-box');
  if (articleBody && tocList && tocBox) {
    var headings = articleBody.querySelectorAll('h2, h3');
    if (headings.length > 0) {
      tocBox.hidden = false;
      headings.forEach(function (h, i) {
        if (!h.id) h.id = 'section-' + (i + 1);
        var li = document.createElement('li');
        var a = document.createElement('a');
        a.href = '#' + h.id;
        a.textContent = h.textContent;
        li.appendChild(a);
        tocList.appendChild(li);
      });
    }
  }

  // 4. Related Posts via Blogger JSONP Feed (Protocol & ?m=1 Normalized)
  var relatedBox = document.getElementById('tv-related-posts');
  if (relatedBox) {
    var label = relatedBox.getAttribute('data-label');
    var currentUrlNorm = normalizeBloggerUrl(
      relatedBox.getAttribute('data-current-url') || window.location.href
    );
    if (label) {
      window.tvRenderRelated = function (data) {
        var entries = (data && data.feed && data.feed.entry) || [];
        var list = document.getElementById('tv-related-list');
        if (!list) return;
        var count = 0;
        entries.forEach(function (entry) {
          if (count >= 4) return;
          var href = '';
          (entry.link || []).forEach(function (l) {
            if (l.rel === 'alternate') href = l.href;
          });
          if (!href || normalizeBloggerUrl(href) === currentUrlNorm) return;
          var li = document.createElement('li');
          var a = document.createElement('a');
          a.href = href;
          a.textContent = (entry.title && entry.title.$t) || 'Related Story';
          li.appendChild(a);
          list.appendChild(li);
          count += 1;
        });
        if (count > 0) relatedBox.hidden = false;
      };
      var s = document.createElement('script');
      s.src =
        '/feeds/posts/default/-/' +
        encodeURIComponent(label) +
        '?alt=json-in-script&callback=tvRenderRelated&max-results=6';
      s.async = true;
      s.onerror = function () {
        relatedBox.hidden = true;
      };
      document.body.appendChild(s);
    }
  }

  // 5. Copy Link & Social Share Intents
  var copyBtn = document.getElementById('tv-copy-link');
  if (copyBtn && navigator.clipboard && navigator.clipboard.writeText) {
    copyBtn.addEventListener('click', function () {
      navigator.clipboard.writeText(window.location.href).then(function () {
        copyBtn.textContent = 'Link Copied';
        setTimeout(function () { copyBtn.textContent = 'Copy Link'; }, 2000);
      });
    });
  }
  var pageUrl = encodeURIComponent(window.location.href);
  var pageTitle = encodeURIComponent(document.title);
  var sx = document.getElementById('tv-share-x');
  var sl = document.getElementById('tv-share-linkedin');
  var sw = document.getElementById('tv-share-whatsapp');
  if (sx) sx.href = 'https://twitter.com/intent/tweet?url=' + pageUrl + '&text=' + pageTitle;
  if (sl) sl.href = 'https://www.linkedin.com/sharing/share-offsite/?url=' + pageUrl;
  if (sw) sw.href = 'https://api.whatsapp.com/send?text=' + pageTitle + '%20' + pageUrl;
})();
//
